def judgeSquareSum(c: int) -> bool:
    # Two pointers: a starts at 0, b starts at integer sqrt(c)
    a = 0
    b = int(c ** 0.5)

    while a <= b:
        s = a * a + b * b
        if s == c:
            return True
        elif s < c:
            a += 1  # increase a to try a larger sum
        else:
            b -= 1  # decrease b to try a smaller sum
    return False
